from pathlib import Path
import re

p = Path('index.html')
s = p.read_text(encoding='utf-8')

SECTIONS = "const sections=[['top','🔴 Top Stories','#dc2626'],['nfl','🏈 NFL','#166534'],['x','𝕏 Top Issues','#111827'],['underreported','🟣 Underreported','#7c3aed'],['world','🌎 World','#2563eb'],['us','🇺🇸 United States','#1e3a8a'],['presidential','🏛️ Presidential','#b45309'],['federal','🏛️ Federal Government','#ca8a04'],['legislation','📜 Laws & Legislation','#a16207'],['nm','🏜️ New Mexico','#0f766e'],['local','📍 Local / Four Corners','#15803d'],['region','🌎 Region','#2563eb'],['technology','💻 Technology','#0891b2'],['gaming','🎮 Gaming & Computing','#7c3aed'],['military','⚔️ Military & War','#991b1b'],['boxoffice','🎬 Box Office','#9a3412']];"
s = re.sub(r'const sections=\[.*?\];', '', s, count=0, flags=re.S)
anchor = "<script>\n"
if anchor not in s: raise SystemExit('Main page script anchor not found')
s = s.replace(anchor, anchor + SECTIONS + "\n", 1)
s = re.sub(r'<nav\s+class=["\']tabs["\']\s+id=["\']tabs["\'][^>]*>.*?</nav>\s*', '', s, flags=re.I | re.S)
needle = '<main class="content" id="news-feed">'
if needle not in s: raise SystemExit('News feed container not found')
s = s.replace(needle, '<nav class="tabs" id="tabs" aria-label="News categories"></nav>' + needle, 1)
marker = '<script id="site-features-v2">'
while marker in s:
    a=s.find(marker); b=s.find('</script>',a)
    if b<0: break
    s=s[:a]+s[b+9:]

STYLE = r'''<style id="site-features-style">
.pull-status{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:0;padding:7px 12px 9px;border-bottom:1px solid var(--ui-line);background:rgba(255,255,255,.72);color:#64748b;font-size:10px;font-weight:650}.pull-status strong{color:#334155}.pull-status .ok{color:#15803d}.pull-status .busy{color:#2563eb}.pull-status .warn{color:#b45309}.pull-status .sep{color:#cbd5e1}.pull-status .count{font-weight:800}.new-badge{display:inline-flex;align-items:center;margin-left:7px;padding:2px 7px;border-radius:999px;background:#dc2626;color:#fff;font-size:9px;font-weight:800;letter-spacing:.35px;vertical-align:middle;box-shadow:0 2px 6px rgba(220,38,38,.2)}.boxoffice-intro{padding:10px 14px;color:#64748b;font-size:11px;line-height:1.5;background:rgba(255,255,255,.6);border-bottom:1px solid var(--ui-line)}.movie-card .movie-details{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}.movie-pill{display:inline-flex;padding:4px 8px;border-radius:999px;background:#f1f5f9;color:#475569;font-size:10px;font-weight:700}.movie-status{display:inline-flex;padding:4px 8px;border-radius:999px;background:#fff7ed;color:#9a3412;font-size:10px;font-weight:800}.movie-showtimes{margin-top:10px;padding:10px;border:1px solid var(--ui-line);border-radius:12px;background:rgba(248,250,252,.85)}.movie-showtimes strong{display:block;margin-bottom:5px}.movie-showtimes small{display:block;color:#64748b;margin-bottom:3px}.movie-news{margin-top:10px}.movie-news a{display:block;margin-top:5px}.boxoffice-section-title{margin:22px 0 8px;padding-left:10px;border-left:3px solid #9a3412;font-size:15px;font-weight:800}@media(max-width:700px){.pull-status{font-size:9px;gap:5px}.pull-status .optional{display:none}.movie-card{padding:16px 13px!important}}
</style>'''
s=s.replace('</head>',STYLE+'\n</head>',1)

SCRIPT = r'''<script id="site-features-v2">
const CANONICAL_SECTIONS=[['top','🔴 Top Stories','#dc2626'],['nfl','🏈 NFL','#166534'],['x','𝕏 Top Issues','#111827'],['underreported','🟣 Underreported','#7c3aed'],['world','🌎 World','#2563eb'],['us','🇺🇸 United States','#1e3a8a'],['presidential','🏛️ Presidential','#b45309'],['federal','🏛️ Federal Government','#ca8a04'],['legislation','📜 Laws & Legislation','#a16207'],['nm','🏜️ New Mexico','#0f766e'],['local','📍 Local / Four Corners','#15803d'],['region','🌎 Region','#2563eb'],['technology','💻 Technology','#0891b2'],['gaming','🎮 Gaming & Computing','#7c3aed'],['military','⚔️ Military & War','#991b1b'],['boxoffice','🎬 Box Office','#9a3412']];
sections=CANONICAL_SECTIONS;
const AUTO_PULL_MS=15*60*1000;
let lastSuccessfulPull=0,nextScheduledPull=0,pullInProgress=false;
let audioContext=null,audioUnlocked=false;
function unlockPopAudio(){try{if(!audioContext)audioContext=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();audioUnlocked=true;}catch(e){audioUnlocked=false;}}
function playNewArticlePop(){if(!audioUnlocked||!audioContext)return;try{const now=audioContext.currentTime;const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.setValueAtTime(620,now);osc.frequency.exponentialRampToValueAtTime(1080,now+0.055);gain.gain.setValueAtTime(0.0001,now);gain.gain.exponentialRampToValueAtTime(0.16,now+0.008);gain.gain.exponentialRampToValueAtTime(0.0001,now+0.085);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now);osc.stop(now+0.09);}catch(e){}}
function normalizeDuplicateKey(item){const link=(item.querySelector('link')?.textContent||'').trim().toLowerCase().replace(/[?#].*$/,'').replace(/\/$/,'');if(link)return 'l:'+link;const title=(item.querySelector('title')?.textContent||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();return 't:'+title;}
function dedupeFetchedItems(items){const seen=new Set(),out=[];for(const item of items){const key=normalizeDuplicateKey(item);if(seen.has(key))continue;seen.add(key);out.push(item);}return {items:out,removed:items.length-out.length};}
function canonicalBuildTabs(){const root=document.getElementById('tabs');if(!root)return;root.innerHTML='';const seen=new Set();CANONICAL_SECTIONS.forEach(([key,label,accent])=>{if(seen.has(key))return;seen.add(key);const b=document.createElement('button');b.className='tab'+(key===active?' active':'');b.textContent=key==='region'&&typeof detectedLocation!=='undefined'&&detectedLocation?'🌎 '+(typeof regionLabels!=='undefined'?regionLabels[detectedRegion]:'Region'):label;b.style.setProperty('--accent',accent);b.onclick=()=>{active=key;localStorage.setItem('underreported-active-tab',active);canonicalBuildTabs();canonicalRender(allItems)};root.appendChild(b)});}
function countdownText(ms){const sec=Math.max(0,Math.ceil(ms/1000));if(sec<=0)return 'now';const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return h?`${h}h ${String(m).padStart(2,'0')}m`:m?`${m}m ${String(s).padStart(2,'0')}s`:`${s}s`;}
function pullStatusHtml(count,failed=false,phase=''){ensurePullStatus();const root=document.getElementById('pull-status');if(!root)return;const last=lastSuccessfulPull?new Date(lastSuccessfulPull):null;const next=nextScheduledPull?new Date(nextScheduledPull):null;const left=next?countdownText(next.getTime()-Date.now()):'—';let lead=failed?'<span class="warn"><strong>⚠ Update failed</strong></span>':pullInProgress?'<span class="busy"><strong>↻ Fetching news…</strong></span>':'<span class="ok"><strong>✓ Auto update active</strong></span>';let extra=phase?`<span>${esc(phase)}</span><span class="sep">·</span>`:'';root.innerHTML=`${lead}<span class="sep">·</span>${extra}<span>Last fetch: <strong>${last?formatDate(last.toISOString()):'—'}</strong></span><span class="sep">·</span><span>Next fetch: <strong>${left}</strong></span><span class="sep">·</span><span class="count">${count||0} stories fetched</span>`;}
function ensurePullStatus(){const toolbar=document.querySelector('.toolbar');if(!toolbar)return;let row=document.getElementById('pull-status');if(!row){row=document.createElement('div');row.id='pull-status';row.className='pull-status';toolbar.insertAdjacentElement('afterend',row);}return row;}
function isFresh(dateText){const d=new Date(dateText);return !isNaN(d)&&Date.now()-d.getTime()<=60*60*1000&&Date.now()>=d.getTime()-5*60*1000;}
function decorateNewBadges(){document.querySelectorAll('.news-item').forEach(card=>{if(card.querySelector('.new-badge'))return;const meta=card.querySelector('.meta span');if(meta&&isFresh(meta.textContent)){const h=card.querySelector('h3');if(h){const badge=document.createElement('span');badge.className='new-badge';badge.textContent='NEW';h.appendChild(badge);}}});}
async function refreshNewsFromPage(manual=false){ensurePullStatus();const btn=document.getElementById('refresh'),status=document.getElementById('status');if(pullInProgress)return;pullInProgress=true;if(btn)btn.disabled=true;if(status)status.textContent=manual?'Fetching…':'Updating…';pullStatusHtml(allItems.length,false,'Connecting to news feed');try{if(manual)unlockPopAudio();const response=await fetch('News?ts='+Date.now(),{cache:'no-store'});if(!response.ok)throw new Error('HTTP '+response.status);pullStatusHtml(allItems.length,false,'Feed downloaded');const text=await response.text();const xml=new DOMParser().parseFromString(text,'text/xml');if(xml.querySelector('parsererror'))throw new Error('Invalid RSS/XML feed');pullStatusHtml(allItems.length,false,'Searching for duplicates');const fetched=[...xml.querySelectorAll('item')];const beforeLinks=new Set(allItems.map(normalizeDuplicateKey));const result=dedupeFetchedItems(fetched);allItems=result.items;const newCount=allItems.filter(item=>!beforeLinks.has(normalizeDuplicateKey(item))).length;if(result.removed)console.info('Client refresh removed',result.removed,'duplicate article(s).');pullStatusHtml(allItems.length,false,result.removed?`Removed ${result.removed} duplicate${result.removed===1?'':'s'}`:'No duplicate articles found');const channel=xml.querySelector('channel');const updated=channel?.querySelector('lastBuildDate')?.textContent||new Date().toISOString();lastSuccessfulPull=Date.now();nextScheduledPull=lastSuccessfulPull+AUTO_PULL_MS;document.getElementById('last-update').textContent='Last update: '+formatDate(updated);if(status)status.textContent=allItems.length+' stories fetched · '+newCount+' new · '+result.removed+' duplicates removed';canonicalBuildTabs();canonicalRender(allItems);decorateNewBadges();if(newCount>0)playNewArticlePop();pullStatusHtml(allItems.length,false,'Fetch complete');}catch(e){if(status)status.textContent='Update failed';pullStatusHtml(allItems.length||0,true,'Unable to fetch feed');console.error(e);}finally{pullInProgress=false;if(btn)btn.disabled=false;}}
function renderStandardCanonical(items){const def=CANONICAL_SECTIONS.find(x=>x[0]===active)||CANONICAL_SECTIONS[0];let list=items.filter(item=>(item.querySelector('category')?.textContent?.trim()||'world')===active);if(active==='region'&&typeof detectedRegion!=='undefined')list=list.filter(item=>(item.querySelector('region')?.textContent?.trim()||'')===detectedRegion);const root=document.getElementById('news-feed');root.innerHTML='';const sec=document.createElement('section');sec.className='section';sec.style.setProperty('--accent',def[2]);const head=document.createElement('div');head.className='section-header';head.innerHTML=`<h2>${esc(def[1])}</h2><span class="count">${list.length} stories</span>`;sec.appendChild(head);const body=document.createElement('div');body.className='section-body';if(!list.length)body.innerHTML='<div class="empty">No stories available right now.</div>';list.forEach((item,i)=>{const ar=document.createElement('article');ar.className='news-item';const title=item.querySelector('title')?.textContent||'Untitled',link=item.querySelector('link')?.textContent||'#',desc=item.querySelector('description')?.textContent||'',why=item.querySelector('whyMatters')?.textContent||'',date=item.querySelector('pubDate')?.textContent||'',source=item.querySelector('source')?.textContent||'';ar.innerHTML=`<h3><a href="${esc(link)}" target="_blank" rel="noopener noreferrer">${i+1}. ${esc(title)}</a></h3>${desc?`<p class="description">${esc(desc)}</p>`:''}${why?`<div class="why">${esc(why)}</div>`:''}<div class="meta"><span>${esc(formatDate(date))}</span>${source?`<span class="source">${esc(source)}</span>`:''}</div>`;body.appendChild(ar)});sec.appendChild(body);root.appendChild(sec);decorateNewBadges();}
function renderBoxOffice(){const root=document.getElementById('news-feed');root.innerHTML='<section class="section"><div class="section-header"><h2>🎬 Box Office</h2><span class="count">Movies, releases & Farmington showtimes</span></div><div class="section-body"><div class="loading">Loading movie information…</div></div></section>';fetch('boxoffice.json?ts='+Date.now(),{cache:'no-store'}).then(r=>r.json()).then(data=>{const movies=data.movies||[];const body=root.querySelector('.section-body');body.innerHTML='';const intro=document.createElement('div');intro.className='boxoffice-intro';intro.innerHTML='Local theater information is for <strong>Farmington, NM</strong>. Showtimes can change during the day; use the source link to confirm before heading out.';body.appendChild(intro);const local=movies.filter(m=>m.status==='In theaters');const upcoming=movies.filter(m=>m.status==='Upcoming');function addHeading(t){const h=document.createElement('div');h.className='boxoffice-section-title';h.textContent=t;body.appendChild(h)}function addMovie(m,status){const ar=document.createElement('article');ar.className='news-item movie-card';const details=[m.rating,m.runtime,m.genres,m.releaseDate?'Release '+new Date(m.releaseDate+'T12:00:00').toLocaleDateString([], {month:'short',day:'numeric',year:'numeric'}):''].filter(Boolean);let shows='';if(m.theaters?.length){shows='<div class="movie-showtimes"><strong>📍 Farmington showtimes</strong>'+m.theaters.map(t=>`<small><b>${esc(t.name)}</b>: ${esc((t.showtimes||[]).join(' · '))}</small>`).join('')+'<small><a href="https://www.showtimes.com/movie-times/farmington-nm/" target="_blank" rel="noopener noreferrer">Verify showtimes</a></small></div>';}let news='';if(m.news?.length){news='<div class="movie-news"><div class="underreported-label">Movie news</div>'+m.news.map(n=>`<a href="${esc(n.link)}" target="_blank" rel="noopener noreferrer">${esc(n.title)}</a>`).join('')+'</div>';}ar.innerHTML=`<div><span class="movie-status">${esc(status)}</span></div><h3>${esc(m.title)}</h3><div class="movie-details">${details.map(x=>`<span class="movie-pill">${esc(x)}</span>`).join('')}</div>${m.description?`<p class="description">${esc(m.description)}</p>`:''}${shows}${news}`;body.appendChild(ar);}if(local.length){addHeading('🍿 New & still in theaters');local.forEach(m=>addMovie(m,'IN THEATERS'));}if(upcoming.length){addHeading('🗓 Upcoming releases');upcoming.slice(0,25).forEach(m=>addMovie(m,'UPCOMING'));}if(!local.length&&!upcoming.length)body.innerHTML+='<div class="empty">Movie data is temporarily unavailable.</div>';const foot=document.createElement('div');foot.className='meta';foot.innerHTML=`<span>Updated ${esc(formatDate(data.updatedAt||new Date().toISOString()))}</span><span class="source"><a href="https://www.showtimes.com/movie-times/farmington-nm/" target="_blank" rel="noopener noreferrer">Showtimes.com</a> · <a href="https://www.the-numbers.com/movies/release-schedule/2026" target="_blank" rel="noopener noreferrer">The Numbers</a></span>`;body.appendChild(foot);}).catch(()=>{root.querySelector('.section-body').innerHTML='<div class="empty">Movie data is temporarily unavailable. Try Refresh.</div>';});}
function canonicalRender(items){if(active==='boxoffice'){renderBoxOffice();return}if(active==='nfl'&&typeof renderNfl==='function'){renderNfl();setTimeout(decorateNewBadges,100);return}if(active==='x'&&typeof renderXIssues==='function'){renderXIssues(items);setTimeout(decorateNewBadges,100);return}if(active==='underreported'&&typeof renderUnderreported==='function'){renderUnderreported(items);setTimeout(decorateNewBadges,100);return}renderStandardCanonical(items);}
window.buildTabs=canonicalBuildTabs;window.render=canonicalRender;window.loadNews=refreshNewsFromPage;
ensurePullStatus();canonicalBuildTabs();
setInterval(()=>pullStatusHtml(allItems.length||0,false),1000);
setInterval(()=>{if(lastSuccessfulPull&&Date.now()>=nextScheduledPull&&!pullInProgress){refreshNewsFromPage(false);}},5000);
setInterval(()=>{if(allItems.length)decorateNewBadges();},60*1000);
loadNews(false);
</script>'''
s=s.replace('</body>',SCRIPT+'\n</body>',1)
p.write_text(s,encoding='utf-8')
print('Added client-side duplicate search/removal and a single Web Audio pop for new articles.')